import { Ionicons } from "@expo/vector-icons"
import AsyncStorage from "@react-native-async-storage/async-storage"
import * as DocumentPicker from "expo-document-picker"
import { StatusBar } from "expo-status-bar"
import { useCallback, useEffect, useRef, useState } from "react"
import type React from "react"
import { ActivityIndicator, Alert, FlatList, KeyboardAvoidingView, Modal, Platform, Pressable, RefreshControl, ScrollView, StatusBar as NativeStatusBar, StyleSheet, Switch, Text, TextInput, useColorScheme, View } from "react-native"
import { SafeAreaProvider, useSafeAreaInsets } from "react-native-safe-area-context"
import { clearToken, configureServer, DEFAULT_SERVER, getServerURL, login, request, restoreConnection, streamRequest, uploadFile } from "./src/api"
import { paletteFor, type Palette } from "./src/theme"
import type { Agent, ChatToolCall, Session, SessionMessage, ThemeMode, User } from "./src/types"

const PREFS_KEY = "veloce.mobile.preferences"
type Tab = "chat" | "explore" | "library" | "settings"
type ExploreKind = "agents" | "knowledge" | "groups" | "skills" | "mcp"
type LibraryKind = "files" | "devices" | "workspaces" | "deliveries" | "tasks" | "memories"
type Preferences = { theme: ThemeMode; language: "zh" | "en" }
const defaultPreferences: Preferences = { theme: "system", language: "zh" }
type ChatAttachment = { id: string; storageID?: string; name: string; type: string; size: number; text: string; binary: boolean; truncated: boolean }
type SessionOption = { id: string; name: string; description?: string }

export default function App() { return <SafeAreaProvider><VeloceApp /></SafeAreaProvider> }

function VeloceApp() {
  const systemTheme = useColorScheme()
  const [ready, setReady] = useState(false)
  const [authenticated, setAuthenticated] = useState(false)
  const [preferences, setPreferences] = useState<Preferences>(defaultPreferences)
  const colors = paletteFor(preferences.theme === "system" ? (systemTheme === "dark" ? "dark" : "light") : preferences.theme)
  const savePreferences = useCallback(async (next: Preferences) => { setPreferences(next); await AsyncStorage.setItem(PREFS_KEY, JSON.stringify(next)) }, [])
  useEffect(() => { Promise.all([restoreConnection(), AsyncStorage.getItem(PREFS_KEY)]).then(([connection, saved]) => { if (saved) setPreferences({ ...defaultPreferences, ...JSON.parse(saved) }); setAuthenticated(Boolean(connection.token)); setReady(true) }).catch(() => setReady(true)) }, [])
  if (!ready) return <Loading colors={colors} />
  return <View style={[styles.app, { backgroundColor: colors.background }]}><StatusBar style={colors.background === "#171717" ? "light" : "dark"} />{authenticated ? <Main colors={colors} preferences={preferences} savePreferences={savePreferences} onLogout={() => setAuthenticated(false)} /> : <Login colors={colors} onLoggedIn={() => setAuthenticated(true)} />}</View>
}

function Login({ colors, onLoggedIn }: { colors: Palette; onLoggedIn: () => void }) {
  const insets = useSafeAreaInsets(); const [identifier, setIdentifier] = useState(""); const [password, setPassword] = useState(""); const [server, setServer] = useState(getServerURL()); const [busy, setBusy] = useState(false); const [showServer, setShowServer] = useState(false); const [error, setError] = useState("")
  const submit = async () => { setBusy(true); setError(""); try { await login(identifier.trim(), password); onLoggedIn() } catch (e) { setError(message(e)) } finally { setBusy(false) } }
  const saveServer = async () => { try { await configureServer(server); setShowServer(false); setError("") } catch (e) { setError(message(e)) } }
  return <View style={[styles.safe, { paddingTop: topInset(insets.top) }]}><KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : undefined} style={styles.center}><View style={[styles.loginCard, { backgroundColor: colors.card, borderColor: colors.border }]}><View style={[styles.logo, { backgroundColor: colors.primary }]}><Ionicons name="sparkles" size={28} color={colors.primaryText} /></View><Text style={[styles.brand, { color: colors.text }]}>Veloce</Text><Text style={[styles.subtitle, { color: colors.muted }]}>你的 AI 工作台</Text><Field colors={colors} placeholder="用户名或邮箱" value={identifier} onChangeText={setIdentifier} autoCapitalize="none" /><Field colors={colors} placeholder="密码" value={password} onChangeText={setPassword} secureTextEntry onSubmitEditing={submit} />
    {error ? <Text style={[styles.error, { color: colors.destructive }]}>{error}</Text> : null}<Button colors={colors} title={busy ? "登录中…" : "登录"} onPress={submit} disabled={busy || !identifier.trim() || !password} /><Pressable onPress={() => setShowServer(true)} style={styles.serverLink}><Ionicons name="server-outline" size={15} color={colors.muted} /><Text style={[styles.small, { color: colors.muted }]} numberOfLines={1}>服务地址：{getServerURL()}</Text></Pressable><Text style={[styles.loginFootnote, { color: colors.muted }]}>OAuth、通行密钥和验证码登录请使用 Web 端。</Text></View></KeyboardAvoidingView>
    <Modal visible={showServer} transparent animationType="fade"><ModalSheet colors={colors} title="服务器连接" onClose={() => setShowServer(false)}><Text style={[styles.sheetDescription, { color: colors.muted }]}>请输入 Veloce 服务端地址。实体设备请使用局域网 IP。</Text><Field colors={colors} value={server} onChangeText={setServer} placeholder={DEFAULT_SERVER} autoCapitalize="none" /><Button colors={colors} title="保存地址" onPress={saveServer} /></ModalSheet></Modal></View>
}

function Main({ colors, preferences, savePreferences, onLogout }: { colors: Palette; preferences: Preferences; savePreferences: (p: Preferences) => void; onLogout: () => void }) {
  const [tab, setTab] = useState<Tab>("chat"); const insets = useSafeAreaInsets()
  return <View style={[styles.safe, { paddingTop: topInset(insets.top) }]}><View style={styles.flex}>{tab === "chat" && <ChatScreen colors={colors} />} {tab === "explore" && <ExploreScreen colors={colors} />} {tab === "library" && <LibraryScreen colors={colors} />} {tab === "settings" && <SettingsScreen colors={colors} preferences={preferences} savePreferences={savePreferences} onLogout={async () => { await clearToken(); onLogout() }} />}</View><BottomTabs colors={colors} active={tab} onChange={setTab} bottom={Math.max(insets.bottom, 8)} /></View>
}

function ChatScreen({ colors }: { colors: Palette }) {
  const [sessions, setSessions] = useState<Session[]>([]); const [activeID, setActiveID] = useState(""); const [draft, setDraft] = useState(""); const [loading, setLoading] = useState(true); const [sending, setSending] = useState(false); const [drawer, setDrawer] = useState(false); const [error, setError] = useState(""); const [agents, setAgents] = useState<Agent[]>([]); const [models, setModels] = useState<string[]>([]); const [agentID, setAgentID] = useState("default"); const [model, setModel] = useState(""); const [runMode, setRunMode] = useState<"chat" | "assistant">("chat"); const [optionsOpen, setOptionsOpen] = useState(false); const [skills, setSkills] = useState<SessionOption[]>([]); const [mcpServers, setMCPServers] = useState<SessionOption[]>([]); const [knowledgeBases, setKnowledgeBases] = useState<SessionOption[]>([]); const [skillIDs, setSkillIDs] = useState<string[]>([]); const [mcpIDs, setMCPIDs] = useState<string[]>([]); const [knowledgeIDs, setKnowledgeIDs] = useState<string[]>([]); const [autoCompress, setAutoCompress] = useState(true); const [attachments, setAttachments] = useState<ChatAttachment[]>([]); const [uploading, setUploading] = useState(false); const [renaming, setRenaming] = useState<Session | null>(null); const [renamedTitle, setRenamedTitle] = useState(""); const [activeRunID, setActiveRunID] = useState(""); const abortController = useRef<AbortController | null>(null); const scroll = useRef<ScrollView>(null)
  const load = useCallback(async () => { try { setError(""); const data = await request<Session[]>("/user/advanced-chat/sessions"); const next = Array.isArray(data) ? data : []; setSessions(next); if (!activeID && next[0]) setActiveID(next[0].id) } catch (e) { setError(message(e)) } finally { setLoading(false) } }, [activeID])
  useEffect(() => { void load() }, [])
  useEffect(() => {
    if (!activeRunID) return
    let cancelled = false
    const refreshRun = async () => {
      try {
        const run = await request<{ status?: string }>(`/user/advanced-chat/runs/${encodeURIComponent(activeRunID)}`)
        if (cancelled) return
        await load()
        if (["completed", "failed", "cancelled", "stopped"].includes(run.status || "")) setActiveRunID("")
      } catch (e) { if (!cancelled) setError(message(e)) }
    }
    void refreshRun(); const timer = setInterval(() => void refreshRun(), 1400)
    return () => { cancelled = true; clearInterval(timer) }
  }, [activeRunID, load])
  useEffect(() => { Promise.all([request<Agent[]>("/user/advanced-chat/agents"), request<Array<{ models?: string[] }>>("/user/catalog")]).then(([nextAgents, catalog]) => { const availableAgents = Array.isArray(nextAgents) ? nextAgents : []; setAgents(availableAgents); if (availableAgents[0] && agentID === "default" && !availableAgents.some(agent => agent.id === "default")) setAgentID(availableAgents[0].id); const nextModels = (Array.isArray(catalog) ? catalog : []).flatMap(item => item.models || []); setModels([...new Set(nextModels)]); if (!model && nextModels[0]) setModel(nextModels[0]) }).catch(() => undefined) }, [])
  useEffect(() => { Promise.all([request<any[]>("/user/advanced-chat/skills"), request<any>("/user/advanced-chat/settings"), request<any>("/user/advanced-chat/knowledge-bases")]).then(([nextSkills, settings, bases]) => { setSkills(Array.isArray(nextSkills) ? nextSkills.map(item => ({ id: String(item.id), name: String(item.name || item.id), description: typeof item.description === "string" ? item.description : "" })) : []); const servers = [...(Array.isArray(settings?.builtin_mcp_servers) ? settings.builtin_mcp_servers : []), ...(Array.isArray(settings?.custom_mcp_servers) ? settings.custom_mcp_servers : []), ...(Array.isArray(settings?.mcp_servers) ? settings.mcp_servers : [])]; setMCPServers(uniqueOptions(servers)); const rawBases = Array.isArray(bases?.knowledge_bases) ? bases.knowledge_bases : bases; setKnowledgeBases(Array.isArray(rawBases) ? rawBases.filter(item => item.vectorized !== false).map(item => ({ id: String(item.id), name: String(item.name || item.id), description: typeof item.description === "string" ? item.description : "" })) : []) }).catch(() => undefined) }, [])
  const active = sessions.find(s => s.id === activeID)
  useEffect(() => { if (!active) return; setRunMode(active.run_mode === "assistant" ? "assistant" : "chat"); setAgentID(active.agent_id || "default"); setModel(active.model_name || ""); setSkillIDs(active.skill_ids || []); setMCPIDs(active.mcp_server_ids || []); setKnowledgeIDs(active.knowledge_base_ids || []); setAutoCompress(active.auto_compress_context !== false) }, [activeID, sessions])
  const newChat = () => { setActiveID(""); setDraft(""); setDrawer(false) }
  const chooseAttachments = async () => {
    if (uploading) return
    const picked = await DocumentPicker.getDocumentAsync({ multiple: true, copyToCacheDirectory: false })
    if (picked.canceled || !picked.assets.length) return
    setUploading(true); setError("")
    try {
      const next: ChatAttachment[] = []
      for (const asset of picked.assets) {
        const result = await uploadFile("/user/advanced-chat/files", asset)
        const file = result.file
        if (!file?.id) continue
        next.push({ id: `attachment-${file.id}`, storageID: file.id, name: file.name || asset.name, type: file.type || asset.mimeType || "application/octet-stream", size: file.size || asset.size || 0, text: result.content?.text || "", binary: result.content?.binary === true, truncated: result.content?.truncated === true })
      }
      setAttachments(current => [...current, ...next.filter(item => !current.some(existing => existing.storageID === item.storageID))])
    } catch (e) { setError(message(e)) } finally { setUploading(false) }
  }
  const send = async () => { const prompt = draft.trim(); const activeAttachments = attachments; if ((!prompt && activeAttachments.length === 0) || sending || uploading) return; setDraft(""); setAttachments([]); setSending(true); setError(""); const now = new Date().toISOString(); const messageContent = contentWithAttachments(prompt, activeAttachments); const userMessage: SessionMessage = { id: `mobile-user-${Date.now()}`, role: "user", content: messageContent, created_at: now }; const assistantID = `mobile-assistant-${Date.now()}`; const assistantMessage: SessionMessage = { id: assistantID, role: "assistant", content: "正在思考…", created_at: now }; const initialTitle = prompt || activeAttachments[0]?.name || "新对话"; const existing = active || { id: `mobile-${Date.now()}`, title: initialTitle.slice(0, 40), messages: [], run_mode: runMode, created_at: now }; const messages = [...(existing.messages || []), userMessage]; const optimistic: Session = { ...existing, title: existing.title || initialTitle.slice(0, 40), run_mode: runMode, agent_id: agentID, model_name: model, skill_ids: skillIDs, mcp_server_ids: mcpIDs, knowledge_base_ids: knowledgeIDs, auto_compress_context: autoCompress, messages: [...messages, assistantMessage] }; const updateAssistant = (updater: (item: SessionMessage) => SessionMessage) => setSessions(current => current.map(session => session.id === optimistic.id ? { ...session, messages: session.messages.map(item => item.id === assistantID ? updater(item) : item) } : session)); setSessions(current => [optimistic, ...current.filter(s => s.id !== optimistic.id)]); setActiveID(optimistic.id)
    const controller = new AbortController(); abortController.current = controller
    try { await streamRequest("/user/advanced-chat/completions", { session_id: optimistic.id, title: optimistic.title, model, channel_id: 0, mode: runMode, messages: messages.map(({ id, role, content }) => ({ id, role, content, tool_calls: [] })), agent_id: agentID, agent_group_id: "", skill_ids: optimistic.skill_ids || [], mcp_server_ids: optimistic.mcp_server_ids || [], knowledge_base_ids: optimistic.knowledge_base_ids || [], connector_device_id: "", connector_workspace_path: "", connector_auto_approve: false, connector_approval_mode: "manual", connector_command_prefixes: [], auto_compress_context: autoCompress, disabled_tool_groups: [], stream: true }, event => { if (event.type === "text" && typeof event.payload?.delta === "string") updateAssistant(item => ({ ...item, content: item.content === "正在思考…" ? event.payload.delta : item.content + event.payload.delta })); else if (event.type === "status" && !event.payload?.message?.includes("completed")) updateAssistant(item => item.content === "正在思考…" ? { ...item, content: "正在处理请求…" } : item); else if (event.type === "tool_call") updateAssistant(item => ({ ...item, tool_calls: [...(item.tool_calls || []), event.payload as ChatToolCall] })); else if (event.type === "done") { const final = event.payload?.message; if (typeof final?.content === "string") updateAssistant(item => ({ ...item, content: final.content || "已完成", tool_calls: Array.isArray(event.payload?.tool_call_details) ? event.payload.tool_call_details : item.tool_calls })); const serverSession = event.payload?.session as Session | undefined; if (serverSession?.id) { setSessions(current => [serverSession, ...current.filter(session => session.id !== serverSession.id)]); setActiveID(serverSession.id) }; const runID = typeof event.payload?.run?.id === "string" ? event.payload.run.id : ""; if (runID) { setActiveRunID(runID); updateAssistant(item => item.content === "正在思考…" ? { ...item, content: "任务已提交，正在运行…" } : item) } } else if (event.type === "error") throw new Error(event.payload?.error || "对话生成失败") }, controller.signal); await load() } catch (e) { if ((e as Error).name === "AbortError") updateAssistant(item => ({ ...item, content: item.content === "正在思考…" ? "已停止" : item.content })); else { updateAssistant(item => ({ ...item, content: item.content === "正在思考…" ? "" : item.content })); setError(message(e)) } } finally { abortController.current = null; setSending(false); setTimeout(() => scroll.current?.scrollToEnd({ animated: true }), 80) } }
  const stop = () => { abortController.current?.abort(); if (activeRunID) void request(`/user/advanced-chat/runs/${encodeURIComponent(activeRunID)}/stop`, { method: "POST" }).catch(e => setError(message(e))).finally(() => setActiveRunID("")) }
  const remove = (session: Session) => Alert.alert("会话操作", `「${session.title || "未命名会话"}」`, [{ text: "取消", style: "cancel" }, { text: "重命名", onPress: () => { setRenaming(session); setRenamedTitle(session.title || "未命名会话") } }, { text: "删除", style: "destructive", onPress: async () => { try { await request(`/user/advanced-chat/sessions/${encodeURIComponent(session.id)}`, { method: "DELETE" }); setSessions(current => current.filter(s => s.id !== session.id)); if (activeID === session.id) setActiveID("") } catch (e) { setError(message(e)) } } }])
  const saveTitle = async () => { if (!renaming || !renamedTitle.trim()) return; try { const saved = await request<Session>(`/user/advanced-chat/sessions/${encodeURIComponent(renaming.id)}`, { method: "PUT", body: { title: renamedTitle.trim() } }); setSessions(current => current.map(item => item.id === renaming.id ? { ...item, ...saved, title: saved.title || renamedTitle.trim() } : item)); setRenaming(null) } catch (e) { setError(message(e)) } }
  const openSession = async (sessionID: string) => { setActiveID(sessionID); setDrawer(false); try { const session = await request<Session>(`/user/advanced-chat/sessions/${encodeURIComponent(sessionID)}`); setSessions(current => [session, ...current.filter(item => item.id !== session.id)]) } catch (e) { setError(message(e)) } }
  const toggleOption = (id: string, current: string[], update: (next: string[]) => void) => update(current.includes(id) ? current.filter(item => item !== id) : [...current, id])
  const saveOptions = async () => { const next: Session = { ...(active || { id: "", title: "", messages: [] }), run_mode: runMode, agent_id: agentID, model_name: model, skill_ids: skillIDs, mcp_server_ids: mcpIDs, knowledge_base_ids: knowledgeIDs, auto_compress_context: autoCompress }; setOptionsOpen(false); if (!active?.id) return; setSessions(current => current.map(session => session.id === active.id ? { ...session, ...next } : session)); try { const saved = await request<Session>(`/user/advanced-chat/sessions/${encodeURIComponent(active.id)}`, { method: "PUT", body: sessionSnapshot(next) }); setSessions(current => current.map(session => session.id === active.id ? { ...session, ...saved } : session)) } catch (e) { setError(message(e)) } }
  return <><View style={styles.flex}><Header colors={colors} title={active?.title || "新对话"} left="menu-outline" onLeft={() => setDrawer(true)} right="options-outline" onRight={() => setOptionsOpen(true)} /><ScrollView ref={scroll} style={styles.flex} contentContainerStyle={[styles.chatContent, !active?.messages?.length && styles.chatEmpty]} onContentSizeChange={() => scroll.current?.scrollToEnd({ animated: true })}>{loading ? <Loading colors={colors} /> : active?.messages?.length ? active.messages.map(m => <MessageBubble key={m.id} colors={colors} item={m} />) : <Welcome colors={colors} onSuggestion={setDraft} />}{sending || activeRunID ? <View style={[styles.typing, { backgroundColor: colors.bubble }]}><ActivityIndicator size="small" color={colors.muted} /><Text style={{ color: colors.muted }}>{activeRunID ? "助理正在执行任务…" : "正在生成回复…"}</Text></View> : null}{error ? <Text style={[styles.error, { color: colors.destructive }]}>{error}</Text> : null}</ScrollView>{attachments.length ? <AttachmentChips colors={colors} attachments={attachments} onRemove={id => setAttachments(current => current.filter(item => item.id !== id))} /> : null}<Composer colors={colors} value={draft} onChangeText={setDraft} onSend={send} onStop={stop} onAttach={chooseAttachments} running={sending || Boolean(activeRunID)} sendDisabled={uploading} /></View>
    <Modal visible={drawer} animationType="slide" transparent><View style={styles.drawerOverlay}><Pressable style={styles.overlaySpace} onPress={() => setDrawer(false)} /><View style={[styles.drawer, { backgroundColor: colors.card, borderColor: colors.border }]}><View style={styles.drawerHeader}><Text style={[styles.drawerTitle, { color: colors.text }]}>会话</Text><IconButton colors={colors} icon="add" onPress={newChat} /></View><Button colors={colors} title="新建会话" icon="add" onPress={newChat} /><FlatList data={sessions} keyExtractor={s => s.id} style={styles.sessionList} renderItem={({ item }) => <Pressable onPress={() => void openSession(item.id)} onLongPress={() => remove(item)} style={[styles.sessionRow, item.id === activeID && { backgroundColor: colors.input }]}><Ionicons name="chatbubble-outline" size={17} color={colors.muted} /><Text numberOfLines={1} style={[styles.sessionName, { color: colors.text }]}>{item.title || "未命名会话"}</Text></Pressable>} ListEmptyComponent={<Text style={[styles.emptyText, { color: colors.muted }]}>还没有历史会话</Text>} /></View></View></Modal>
    <Modal visible={optionsOpen} transparent animationType="slide"><ModalSheet colors={colors} title="会话设置" onClose={() => setOptionsOpen(false)}><ScrollView style={styles.optionsScroll} contentContainerStyle={styles.optionsContent}><Text style={[styles.sheetDescription, { color: colors.muted }]}>运行模式</Text><View style={styles.optionRow}><Pill colors={colors} active={runMode === "chat"} label="普通聊天" onPress={() => setRunMode("chat")} /><Pill colors={colors} active={runMode === "assistant"} label="助理模式" onPress={() => setRunMode("assistant")} /></View><Text style={[styles.sheetDescription, { color: colors.muted }]}>智能体</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.optionRow}>{agents.map(agent => <Pill key={agent.id} colors={colors} active={agent.id === agentID} label={agent.name} onPress={() => { setAgentID(agent.id); if (agent.default_model) setModel(agent.default_model) }} />)}</ScrollView><Text style={[styles.sheetDescription, { color: colors.muted }]}>模型</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.optionRow}>{models.map(item => <Pill key={item} colors={colors} active={item === model} label={item} onPress={() => setModel(item)} />)}</ScrollView><OptionSelector colors={colors} title="技能" options={skills} selected={skillIDs} onToggle={id => toggleOption(id, skillIDs, setSkillIDs)} /><OptionSelector colors={colors} title="MCP 工具" options={mcpServers} selected={mcpIDs} onToggle={id => toggleOption(id, mcpIDs, setMCPIDs)} /><OptionSelector colors={colors} title="知识库" options={knowledgeBases} selected={knowledgeIDs} onToggle={id => toggleOption(id, knowledgeIDs, setKnowledgeIDs)} /><View style={[styles.compressionRow, { borderColor: colors.border }]}><View style={styles.resourceText}><Text style={[styles.resourceName, { color: colors.text }]}>自动压缩上下文</Text><Text style={[styles.resourceDetail, { color: colors.muted }]}>上下文接近限制时自动整理历史消息</Text></View><Switch value={autoCompress} onValueChange={setAutoCompress} trackColor={{ false: colors.border, true: colors.primary }} /></View><Button colors={colors} title={active ? "保存会话设置" : "应用到新会话"} onPress={saveOptions} /></ScrollView></ModalSheet></Modal>
    <Modal visible={Boolean(renaming)} transparent animationType="slide"><ModalSheet colors={colors} title="重命名会话" onClose={() => setRenaming(null)}><Field colors={colors} value={renamedTitle} onChangeText={setRenamedTitle} placeholder="会话标题" autoFocus /><Button colors={colors} title="保存标题" onPress={saveTitle} disabled={!renamedTitle.trim()} /></ModalSheet></Modal></>
}

function ExploreScreen({ colors }: { colors: Palette }) {
  const [kind, setKind] = useState<ExploreKind>("agents"); const [items, setItems] = useState<any[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [editor, setEditor] = useState(false); const [name, setName] = useState(""); const [description, setDescription] = useState("")
  const config: Record<ExploreKind, { label: string; endpoint: string; icon: keyof typeof Ionicons.glyphMap }> = { agents: { label: "智能体", endpoint: "/user/advanced-chat/agents", icon: "hardware-chip-outline" }, knowledge: { label: "知识库", endpoint: "/user/advanced-chat/knowledge-bases", icon: "library-outline" }, groups: { label: "聊天群组", endpoint: "/user/advanced-chat/chat-groups", icon: "people-outline" }, skills: { label: "技能", endpoint: "/user/advanced-chat/skills", icon: "sparkles-outline" }, mcp: { label: "MCP", endpoint: "/user/advanced-chat/settings", icon: "extension-puzzle-outline" } }
  const load = useCallback(async () => { setLoading(true); try { const data = await request<any>(config[kind].endpoint); const next = kind === "knowledge" ? data?.knowledge_bases || data : kind === "mcp" ? [...(data?.builtin_mcp_servers || []), ...(data?.custom_mcp_servers || []), ...(data?.mcp_servers || [])] : data; setItems(Array.isArray(next) ? next : []) } catch (e) { setError(message(e)); setItems([]) } finally { setLoading(false) } }, [kind])
  useEffect(() => { void load() }, [load])
  const canCreate = kind === "agents" || kind === "knowledge" || kind === "groups"
  const create = async () => { if (!name.trim()) return; try { const body = kind === "agents" ? { name: name.trim(), prompt: description.trim(), default_model: "", stream: true, skill_ids: [], mcp_server_ids: [], knowledge_base_ids: [] } : kind === "knowledge" ? { name: name.trim(), description: description.trim() } : { name: name.trim(), description: description.trim(), agent_ids: [] }; await request(config[kind].endpoint, { method: "POST", body }); setEditor(false); setName(""); setDescription(""); await load() } catch (e) { setError(message(e)) } }
  return <><View style={styles.flex}><Header colors={colors} title="工作台" /><View style={[styles.segment, { borderColor: colors.border }]}>{(Object.keys(config) as ExploreKind[]).map(key => <Pressable key={key} onPress={() => setKind(key)} style={[styles.segmentItem, kind === key && { backgroundColor: colors.primary }]}><Ionicons name={config[key].icon} size={16} color={kind === key ? colors.primaryText : colors.muted} /><Text style={[styles.segmentLabel, { color: kind === key ? colors.primaryText : colors.muted }]}>{config[key].label}</Text></Pressable>)}</View><ResourceList colors={colors} title={config[kind].label} items={items} loading={loading} error={error} onRefresh={load} onCreate={canCreate ? () => setEditor(true) : undefined} icon={config[kind].icon} /></View>
    <Modal visible={editor} transparent animationType="slide"><ModalSheet colors={colors} title={`新建${config[kind].label}`} onClose={() => setEditor(false)}><Field colors={colors} placeholder="名称" value={name} onChangeText={setName} /><Field colors={colors} placeholder={kind === "agents" ? "系统提示词（可选）" : "说明（可选）"} value={description} onChangeText={setDescription} multiline /><Button colors={colors} title="创建" onPress={create} disabled={!name.trim()} /></ModalSheet></Modal></>
}

function LibraryScreen({ colors }: { colors: Palette }) {
  const [kind, setKind] = useState<LibraryKind>("files"); const [items, setItems] = useState<any[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState("")
  const config: Record<LibraryKind, { label: string; endpoint: string; icon: keyof typeof Ionicons.glyphMap }> = { files: { label: "文件库", endpoint: "/user/advanced-chat/files", icon: "document-text-outline" }, devices: { label: "设备", endpoint: "/user/advanced-chat/devices", icon: "laptop-outline" }, workspaces: { label: "工作区", endpoint: "/user/advanced-chat/workspaces", icon: "folder-open-outline" }, deliveries: { label: "结果投递", endpoint: "/user/advanced-chat/deliveries", icon: "send-outline" }, tasks: { label: "定时任务", endpoint: "/user/advanced-chat/scheduled-tasks", icon: "calendar-outline" }, memories: { label: "记忆", endpoint: "/user/advanced-chat/memories", icon: "bulb-outline" } }
  const load = useCallback(async () => { setLoading(true); try { const data = await request<any>(config[kind].endpoint); const next = data?.files || data?.devices || data?.workspaces || data?.deliveries || data?.tasks || data?.memories || data; setItems(Array.isArray(next) ? next : []) } catch (e) { setError(message(e)); setItems([]) } finally { setLoading(false) } }, [kind])
  useEffect(() => { void load() }, [load])
  return <View style={styles.flex}><Header colors={colors} title="资源" /><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.pills}>{(Object.keys(config) as LibraryKind[]).map(key => <Pill key={key} colors={colors} active={key === kind} label={config[key].label} onPress={() => setKind(key)} />)}</ScrollView><ResourceList colors={colors} title={config[kind].label} items={items} loading={loading} error={error} onRefresh={load} icon={config[kind].icon} /></View>
}

function SettingsScreen({ colors, preferences, savePreferences, onLogout }: { colors: Palette; preferences: Preferences; savePreferences: (p: Preferences) => void; onLogout: () => void }) {
  const [user, setUser] = useState<User | null>(null); const [serverOpen, setServerOpen] = useState(false); const [server, setServer] = useState(getServerURL()); const [messageText, setMessageText] = useState("")
  useEffect(() => { request<User>("/user/me").then(setUser).catch(e => setMessageText(message(e))) }, [])
  const saveServer = async () => { try { await configureServer(server); setServerOpen(false); setMessageText("服务地址已保存，重新登录后生效") } catch (e) { setMessageText(message(e)) } }
  return <><ScrollView style={styles.flex} contentContainerStyle={styles.settingsContent}><Header colors={colors} title="设置" /><Section colors={colors} title="账户"><SettingRow colors={colors} icon="person-circle-outline" label={user?.username || user?.email || "账户信息加载中"} detail={user?.email || ""} /><SettingRow colors={colors} icon="server-outline" label="服务器连接" detail={getServerURL()} onPress={() => setServerOpen(true)} /></Section><Section colors={colors} title="外观"><View style={styles.themeChoices}>{(["light", "dark", "system"] as ThemeMode[]).map(mode => <Pressable key={mode} onPress={() => savePreferences({ ...preferences, theme: mode })} style={[styles.themeChoice, { borderColor: preferences.theme === mode ? colors.primary : colors.border, backgroundColor: preferences.theme === mode ? colors.input : colors.card }]}><Ionicons name={mode === "light" ? "sunny-outline" : mode === "dark" ? "moon-outline" : "phone-portrait-outline"} size={18} color={colors.text} /><Text style={{ color: colors.text }}>{mode === "light" ? "浅色" : mode === "dark" ? "深色" : "跟随系统"}</Text></Pressable>)}</View><SettingRow colors={colors} icon="language-outline" label="语言" detail={preferences.language === "zh" ? "简体中文" : "English"} right={<Switch value={preferences.language === "en"} onValueChange={v => savePreferences({ ...preferences, language: v ? "en" : "zh" })} trackColor={{ false: colors.border, true: colors.primary }} />} /></Section><Section colors={colors} title="关于"><SettingRow colors={colors} icon="information-circle-outline" label="Veloce Mobile" detail="React Native / Expo" /><SettingRow colors={colors} icon="desktop-outline" label="桌面专属能力" detail="终端、通行密钥与 OAuth 请在 Web/桌面端使用" /></Section>{messageText ? <Text style={[styles.error, { color: colors.destructive }]}>{messageText}</Text> : null}<Button colors={colors} title="退出登录" icon="log-out-outline" destructive onPress={() => Alert.alert("退出登录", "是否清除此设备上的登录凭据？", [{ text: "取消", style: "cancel" }, { text: "退出", style: "destructive", onPress: onLogout }])} /></ScrollView>
    <Modal visible={serverOpen} transparent animationType="slide"><ModalSheet colors={colors} title="服务器连接" onClose={() => setServerOpen(false)}><Field colors={colors} value={server} onChangeText={setServer} autoCapitalize="none" /><Button colors={colors} title="保存" onPress={saveServer} /></ModalSheet></Modal></>
}

function ResourceList({ colors, title, items, loading, error, onRefresh, onCreate, icon }: { colors: Palette; title: string; items: any[]; loading: boolean; error: string; onRefresh: () => void; onCreate?: () => void; icon: keyof typeof Ionicons.glyphMap }) { return <FlatList style={styles.flex} contentContainerStyle={styles.listContent} data={items} keyExtractor={(item, index) => String(item.id || item.name || index)} refreshControl={<RefreshControl refreshing={loading} onRefresh={onRefresh} tintColor={colors.muted} />} ListHeaderComponent={<View style={styles.listHeader}><View><Text style={[styles.pageTitle, { color: colors.text }]}>{title}</Text><Text style={[styles.small, { color: colors.muted }]}>{items.length} 项</Text></View>{onCreate ? <IconButton colors={colors} icon="add" onPress={onCreate} /> : null}</View>} ListEmptyComponent={loading ? <Loading colors={colors} /> : <Empty colors={colors} icon={icon} text={error || `暂无${title}`} />} renderItem={({ item }) => <ResourceRow colors={colors} item={item} icon={icon} />} /> }
function ResourceRow({ colors, item, icon }: { colors: Palette; item: any; icon: keyof typeof Ionicons.glyphMap }) { const title = item.name || item.title || item.hostname || item.id || "未命名"; const detail = item.description || item.default_model || item.type || item.path || item.status || item.updated_at || item.created_at || ""; return <View style={[styles.resourceRow, { backgroundColor: colors.card, borderColor: colors.border }]}><View style={[styles.resourceIcon, { backgroundColor: colors.input }]}><Ionicons name={icon} size={20} color={colors.text} /></View><View style={styles.resourceText}><Text style={[styles.resourceName, { color: colors.text }]} numberOfLines={1}>{title}</Text><Text style={[styles.resourceDetail, { color: colors.muted }]} numberOfLines={2}>{String(detail)}</Text></View>{item.online !== undefined ? <View style={[styles.statusDot, { backgroundColor: item.online ? "#22c55e" : colors.muted }]} /> : <Ionicons name="chevron-forward" size={18} color={colors.muted} />}</View> }
function Header({ colors, title, left, onLeft, right, onRight }: { colors: Palette; title: string; left?: keyof typeof Ionicons.glyphMap; onLeft?: () => void; right?: keyof typeof Ionicons.glyphMap; onRight?: () => void }) { return <View style={[styles.header, { borderColor: colors.border, backgroundColor: colors.background }]}><View style={styles.headerSide}>{left ? <IconButton colors={colors} icon={left} onPress={onLeft || (() => {})} /> : null}</View><Text style={[styles.headerTitle, { color: colors.text }]} numberOfLines={1}>{title}</Text><View style={[styles.headerSide, styles.headerRight]}>{right ? <IconButton colors={colors} icon={right} onPress={onRight || (() => {})} /> : null}</View></View> }
function BottomTabs({ colors, active, onChange, bottom }: { colors: Palette; active: Tab; onChange: (t: Tab) => void; bottom: number }) { const tabs: { key: Tab; label: string; icon: keyof typeof Ionicons.glyphMap }[] = [{ key: "chat", label: "聊天", icon: "chatbubbles-outline" }, { key: "explore", label: "工作台", icon: "grid-outline" }, { key: "library", label: "资源", icon: "folder-outline" }, { key: "settings", label: "设置", icon: "settings-outline" }]; return <View style={[styles.tabs, { borderColor: colors.border, backgroundColor: colors.card, paddingBottom: bottom }]}>{tabs.map(tab => <Pressable key={tab.key} onPress={() => onChange(tab.key)} style={styles.tab}><Ionicons name={tab.icon} size={22} color={active === tab.key ? colors.text : colors.muted} /><Text style={[styles.tabLabel, { color: active === tab.key ? colors.text : colors.muted }]}>{tab.label}</Text></Pressable>)}</View> }
function Composer({ colors, value, onChangeText, onSend, onStop, onAttach, running, sendDisabled }: { colors: Palette; value: string; onChangeText: (v: string) => void; onSend: () => void; onStop: () => void; onAttach: () => void; running: boolean; sendDisabled: boolean }) { const blocked = !running && (!value.trim() || sendDisabled); return <View style={[styles.composer, { borderColor: colors.border, backgroundColor: colors.card }]}><Pressable disabled={running || sendDisabled} onPress={onAttach} style={[styles.attachButton, { backgroundColor: colors.input, opacity: running || sendDisabled ? .45 : 1 }]}><Ionicons name="attach-outline" color={colors.text} size={20} /></Pressable><TextInput editable={!running} value={value} onChangeText={onChangeText} placeholder="给 Veloce 发送消息" placeholderTextColor={colors.muted} multiline style={[styles.composerInput, { color: colors.text, backgroundColor: colors.input }]} /><Pressable disabled={blocked} onPress={running ? onStop : onSend} style={[styles.sendButton, { backgroundColor: running ? colors.destructive : colors.primary, opacity: blocked ? .4 : 1 }]}><Ionicons name={running ? "stop" : "arrow-up"} color="#fff" size={20} /></Pressable></View> }
function AttachmentChips({ colors, attachments, onRemove }: { colors: Palette; attachments: ChatAttachment[]; onRemove: (id: string) => void }) { return <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={[styles.attachmentChips, { backgroundColor: colors.card }]}>{attachments.map(item => <View key={item.id} style={[styles.attachmentChip, { borderColor: colors.border, backgroundColor: colors.input }]}><Ionicons name="attach-outline" size={14} color={colors.muted} /><Text numberOfLines={1} style={[styles.attachmentName, { color: colors.text }]}>{item.name}</Text><Pressable onPress={() => onRemove(item.id)}><Ionicons name="close" size={15} color={colors.muted} /></Pressable></View>)}</ScrollView> }
function MessageBubble({ colors, item }: { colors: Palette; item: SessionMessage }) { const user = item.role === "user"; const parsed = parseAttachmentContent(item.content); const textColor = user ? colors.primaryText : colors.text; return <View style={[styles.messageWrap, user && styles.messageUser]}><View style={[styles.message, { backgroundColor: user ? colors.primary : colors.bubble }]}>{parsed.text ? <Text style={[styles.messageText, { color: textColor }]}>{parsed.text}</Text> : null}{parsed.attachments.length ? <View style={styles.messageAttachments}>{parsed.attachments.map((attachment, index) => <View key={`${attachment.name}-${index}`} style={[styles.messageAttachment, { borderColor: user ? "rgba(255,255,255,.35)" : colors.border, backgroundColor: user ? "rgba(255,255,255,.12)" : colors.card }]}><Ionicons name="attach-outline" size={14} color={user ? colors.primaryText : colors.muted} /><View style={styles.resourceText}><Text style={[styles.attachmentName, { color: textColor }]} numberOfLines={1}>{attachment.name}</Text><Text style={[styles.toolCallText, { color: user ? colors.primaryText : colors.muted }]}>{attachment.type} · {attachment.size}</Text></View></View>)}</View> : null}{!user && item.tool_calls?.length ? <View style={styles.toolCalls}>{item.tool_calls.map((tool, index) => <View key={tool.id || `${tool.name}-${index}`} style={[styles.toolCall, { borderColor: colors.border, backgroundColor: colors.card }]}><Ionicons name="construct-outline" size={14} color={colors.muted} /><Text style={[styles.toolCallText, { color: colors.muted }]} numberOfLines={1}>{tool.name || tool.tool || "工具调用"} · {tool.status || "执行中"}</Text></View>)}</View> : null}</View></View> }
function Welcome({ colors, onSuggestion }: { colors: Palette; onSuggestion: (text: string) => void }) { const suggestions = ["帮我整理今天的工作计划", "根据已有资料生成产品方案", "分析这段内容并给出改进建议"] ; return <View style={styles.welcome}><View style={[styles.logo, { backgroundColor: colors.primary }]}><Ionicons name="sparkles" size={30} color={colors.primaryText} /></View><Text style={[styles.welcomeTitle, { color: colors.text }]}>今天想做些什么？</Text><Text style={[styles.welcomeBody, { color: colors.muted }]}>Veloce 可以聊天、调用智能体并处理你的工作资料。</Text><View style={styles.suggestions}>{suggestions.map(s => <Pressable key={s} onPress={() => onSuggestion(s)} style={[styles.suggestion, { borderColor: colors.border, backgroundColor: colors.card }]}><Ionicons name="sparkles-outline" size={16} color={colors.muted} /><Text style={[styles.suggestionText, { color: colors.text }]}>{s}</Text></Pressable>)}</View></View> }
function Section({ colors, title, children }: { colors: Palette; title: string; children: React.ReactNode }) { return <View style={styles.section}><Text style={[styles.sectionTitle, { color: colors.muted }]}>{title}</Text><View style={[styles.sectionCard, { backgroundColor: colors.card, borderColor: colors.border }]}>{children}</View></View> }
function SettingRow({ colors, icon, label, detail, onPress, right }: { colors: Palette; icon: keyof typeof Ionicons.glyphMap; label: string; detail?: string; onPress?: () => void; right?: React.ReactNode }) { return <Pressable disabled={!onPress} onPress={onPress} style={styles.settingRow}><Ionicons name={icon} size={21} color={colors.text} /><View style={styles.settingMain}><Text style={[styles.settingLabel, { color: colors.text }]}>{label}</Text>{detail ? <Text style={[styles.settingDetail, { color: colors.muted }]} numberOfLines={1}>{detail}</Text> : null}</View>{right || (onPress ? <Ionicons name="chevron-forward" size={18} color={colors.muted} /> : null)}</Pressable> }
function Field({ colors, multiline, ...props }: { colors: Palette; multiline?: boolean } & React.ComponentProps<typeof TextInput>) { return <TextInput {...props} multiline={multiline} placeholderTextColor={colors.muted} style={[styles.field, multiline && styles.fieldMultiline, { color: colors.text, borderColor: colors.border, backgroundColor: colors.input }, props.style]} /> }
function Button({ colors, title, onPress, disabled, icon, destructive }: { colors: Palette; title: string; onPress: () => void; disabled?: boolean; icon?: keyof typeof Ionicons.glyphMap; destructive?: boolean }) { return <Pressable disabled={disabled} onPress={onPress} style={[styles.button, { backgroundColor: destructive ? colors.destructive : colors.primary, opacity: disabled ? .45 : 1 }]}>{icon ? <Ionicons name={icon} size={18} color="#fff" /> : null}<Text style={styles.buttonText}>{title}</Text></Pressable> }
function IconButton({ colors, icon, onPress }: { colors: Palette; icon: keyof typeof Ionicons.glyphMap; onPress: () => void }) { return <Pressable onPress={onPress} style={[styles.iconButton, { backgroundColor: colors.input }]}><Ionicons name={icon} size={21} color={colors.text} /></Pressable> }
function Pill({ colors, label, active, onPress }: { colors: Palette; label: string; active: boolean; onPress: () => void }) { return <Pressable onPress={onPress} style={[styles.pill, { backgroundColor: active ? colors.primary : colors.input }]}><Text style={[styles.pillText, { color: active ? colors.primaryText : colors.text }]}>{label}</Text></Pressable> }
function OptionSelector({ colors, title, options, selected, onToggle }: { colors: Palette; title: string; options: SessionOption[]; selected: string[]; onToggle: (id: string) => void }) { return <View style={styles.selector}><Text style={[styles.sheetDescription, { color: colors.muted }]}>{title}</Text>{options.length ? options.map(option => <Pressable key={option.id} onPress={() => onToggle(option.id)} style={[styles.optionItem, { borderColor: colors.border, backgroundColor: selected.includes(option.id) ? colors.input : colors.card }]}><Ionicons name={selected.includes(option.id) ? "checkbox-outline" : "square-outline"} size={19} color={colors.text} /><View style={styles.resourceText}><Text style={[styles.resourceName, { color: colors.text }]}>{option.name}</Text>{option.description ? <Text style={[styles.resourceDetail, { color: colors.muted }]} numberOfLines={1}>{option.description}</Text> : null}</View></Pressable>) : <Text style={[styles.optionEmpty, { color: colors.muted }]}>暂无可用项目</Text>}</View> }
function ModalSheet({ colors, title, children, onClose }: { colors: Palette; title: string; children: React.ReactNode; onClose: () => void }) { return <View style={styles.modalPosition}><Pressable style={styles.modalBackdrop} onPress={onClose} /><View style={[styles.sheet, { backgroundColor: colors.card }]}><View style={styles.sheetHandle} /><View style={styles.sheetHeader}><Text style={[styles.sheetTitle, { color: colors.text }]}>{title}</Text><IconButton colors={colors} icon="close" onPress={onClose} /></View>{children}</View></View> }
function Empty({ colors, icon, text }: { colors: Palette; icon: keyof typeof Ionicons.glyphMap; text: string }) { return <View style={styles.empty}><Ionicons name={icon} size={32} color={colors.muted} /><Text style={[styles.emptyText, { color: colors.muted }]}>{text}</Text></View> }
function Loading({ colors }: { colors: Palette }) { return <View style={styles.loading}><ActivityIndicator size="small" color={colors.muted} /></View> }
function topInset(safeInset: number) { return Math.max(safeInset, Platform.OS === "android" ? NativeStatusBar.currentHeight || 24 : 0) }
function uniqueOptions(items: any[]): SessionOption[] { const seen = new Set<string>(); return items.reduce<SessionOption[]>((result, item) => { const id = typeof item?.id === "string" ? item.id : ""; if (!id || seen.has(id)) return result; seen.add(id); result.push({ id, name: typeof item.name === "string" ? item.name : id, description: typeof item.description === "string" ? item.description : item.type || "" }); return result }, []) }
function sessionSnapshot(session: Session) { return { id: session.id, title: session.title, run_mode: session.run_mode || "chat", agent_id: session.agent_id || "default", agent_group_id: "", skill_ids: session.skill_ids || [], mcp_server_ids: session.mcp_server_ids || [], knowledge_base_ids: session.knowledge_base_ids || [], connector_device_id: "", connector_workspace_path: "", cloud_sandbox_id: "", connector_auto_approve: false, connector_approval_mode: "manual", connector_command_prefixes: [], model_name: session.model_name || "", user_channel_id: 0, max_tokens: session.max_tokens || 0, temperature: session.temperature ?? null, reasoning_effort: session.reasoning_effort || "", auto_compress_context: session.auto_compress_context !== false, disabled_tool_groups: session.disabled_tool_groups || [], messages: session.messages.map(item => ({ id: item.id, role: item.role, content: item.content, tool_calls: item.tool_calls || [] })) } }
function parseAttachmentContent(content: string) { const attachments: Array<{ name: string; type: string; size: string }> = []; const matcher = /^\[Attachment:\s*(.*?);\s*type=([^;\]]*);\s*size=([^;\]]+)(?:;\s*file_id=[^\]]+)?\]\s*(?:\n[\s\S]*?)(?=^\[Attachment:|\s*$)/gm; let text = content; let match: RegExpExecArray | null; while ((match = matcher.exec(content)) !== null) { attachments.push({ name: match[1].trim() || "附件", type: match[2].trim() || "application/octet-stream", size: match[3].trim() || "0 B" }); text = text.replace(match[0], "") } return { text: text.replace(/\n{3,}/g, "\n\n").trim(), attachments } }
function contentWithAttachments(content: string, attachments: ChatAttachment[]) { return [content, ...attachments.map(item => { const header = `[Attachment: ${item.name}; type=${item.type}; size=${formatBytes(item.size)}${item.storageID ? `; file_id=${item.storageID}` : ""}]`; if (!item.text) return `${header}\n${item.type.startsWith("image/") && item.storageID ? "(image attached for model vision input)" : "(binary content omitted)"}`; return `${header}\n${item.text.slice(0, 20000)}${item.truncated ? "\n...(truncated)" : ""}` })].filter(Boolean).join("\n\n") }
function formatBytes(bytes: number) { if (!bytes) return "0 B"; if (bytes < 1024) return `${bytes} B`; if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`; return `${(bytes / 1024 / 1024).toFixed(1)} MB` }
function message(error: unknown) { return error instanceof Error ? error.message : "发生未知错误" }

